div.script:
(function () {
    var left = 50;
    var el = document.getElementById('selfcheck-expire');
    var form = document.getElementById('selfcheck-rotate');
    if (!form) { return; }
    setInterval(function () {
        left -= 1;
        if (left <= 0) {
            form.submit();
            return;
        }
        if (el) {
            el.textContent = left + ' 秒后自动换码';
        }
    }, 1000);
})();

t.script:
function eduBulkAll(box) {
    var form = box.closest('form');
    if (!form) { return; }
    var items = form.querySelectorAll('input[name="ids"]');
    for (var i = 0; i < items.length; i++) {
        if (!items[i].disabled) { items[i].checked = box.checked; }
    }
}

