xpath.script:
function eduBulkAllForm(box, formId) {
    var items = document.querySelectorAll(
        'input[name="ids"][form="' + formId + '"]');
    for (var i = 0; i < items.length; i++) {
        if (!items[i].disabled) { items[i].checked = box.checked; }
    }
}
